"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["338"],{6007(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>h,frontMatter:()=>r,contentTitle:()=>s,toc:()=>d,assets:()=>l});var o=JSON.parse('{"id":"how-to/hardware/samples/nucleo-hl-mqtt","title":"Connecting STM32 Nucleo-based application to AirVantage","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/hardware/samples/nucleo-hl-mqtt.md","sourceDirName":"how-to/hardware/samples","slug":"/how-to/hardware/samples/nucleo-hl-mqtt","permalink":"/personal-av-docs/docs/how-to/hardware/samples/nucleo-hl-mqtt","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/hardware/samples/nucleo-hl-mqtt.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Connecting STM32 Nucleo-based application to AirVantage","sidebar_label":"Connecting STM32 Nucleo-based applicatio","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/hardware/samples/nucleo-hl-mqtt","format":"md"}}'),i=t(4848),a=t(8453);let r={title:"Connecting STM32 Nucleo-based application to AirVantage",sidebar_label:"Connecting STM32 Nucleo-based applicatio",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/hardware/samples/nucleo-hl-mqtt",format:"md"},s,l={},d=[];function c(e){let n={a:"a",code:"code",p:"p",pre:"pre",strong:"strong",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(n.p,{children:[":::note Edition\n",(0,i.jsx)(n.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(n.a,{href:"https://doc.airvantage.net/av/howto/hardware/samples/nucleo-hl-mqtt",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsx)(n.p,{children:'Connecting STM32 Nucleo-based application to AirVantage\nObjective\nThis tutorial describes how to create communication between AirVantage and\nSTM32Nucleo-based system\nusing\nAirPrime HL wireless module\n.\nThe following use cases are covered:\nSending custom data such as sensor values or application data from STM32/Nucleo board to AirVantage\nSending commands or configuration from AirVantage to STM32/Nucleo board\nTo implement this solution, MQTT protocol will be used.\nLet\u2019s develop a simple Alarm system to better showcase the solution in 4 main steps:\nSetup Hardware\nSetup STM32/Nucleo board Software Development Environment\nDefine STM32/Nucleo board-AirVantage Interface\nDevelop a simple Alarm system\nPrerequisite\nHL Shield + Antenna + Power adaptor + USB cable MiniB-A\nAirPrime HL series Module\nSIM card with data call plan\nSTM32 Nucleo-L053R8 + USB cable type B-A\nUSB Hub (3 ports or more) + TTL to Serial USB cable (E.g. TTL-232R)\nLED + PIR Motion detection sensor\nFemale to female wiring cable\nHave an account on AirVantage server : eu.airvantage.net\nPart references used in this tutorial\nAirPrime HL8548 module\nSTM32 Nuleo-L053R8\nHL Shield: Please contact your local Sierra Wireless Technical representative\nAntenna\nPower adapter 12Vdc 1.5A\nUSB Hub\nTTL to Serial USB cable\nUSB-A to USB-B cable\nUSB-A to MiniUSB cable\nPassive Infra-Red (PIR) motion sensor\nLED\nWiring cables\n1 /\nHardware Setup\n2 /\nSoftware Setup\n3 /\nClient-Server Interface\n4 /\nAlarm App\nAny issues ?\nIf you encounter any issue to set up your device, don\u2019t hesitate to use the\ndeveloper forum\nto benefit from the developer community experience.\nStep 1: Hardware Setup\nThis step aims to setup the HL shield properly and stack it to STM32 Nucleo-L053R8 board\nPreparing the HL Shield\nPlace the HL Module into the shield\u2019s module socket. To ensure the correct orientation of the HL Module, use the\ndot\nmark, printed on the top right corner, as reference. It should be aligned with the\ndot\nmark visible within the shield socket. Then place the shielding cover on the module.\nEnsure that jumpers are correctly placed according to the photo (red marks in ellipses)\nConnect the antenna to the \u201C2G/3G/4G RF MAIN\u201D connector.\nInsert a SIM card into the \u201CSIM1\u201D slot, located in the bottom side of the Shield.\nConnect the \u201CMAIN UART\u201D USB port (green ellipse) to USB Hub which is connected to your PC/Mac\nIf USB driver is missing, VCP driver can be downloaded\nhere\nConfigure Nucleo-L053R8 to use D0 and D1 Arduino pins\nBy default, Nucleo boards are configured to have shared UART on pins D0 and D1 with STLink.\nWe need to use these D0 and D1 pins independently so the Nucleo can be stacked under the HL Shield, to achieve this:\nRemove Solder Bridges SB13 and SB14, located in the red area in the photo\nSet Solder Bridges SB62 and SB63 to ON, green area in the photo. (Zero resistors removed from SB13 & SB14 can placed in SB62 & SB63)\nImportant: without this hardware configuration, D0 and D1 cannot be used as serial port to drive the HL Shield.\nIn this case, flying wires should be used (no stacking) to connect Nucleo CN3\'s RX & TX pins to HL Shield\'s counterpart Arduino TX & RX pins. IOREF and GND pins must also be wired.\nStacking HL Shield over Nucleo-L053R8\nRefer to the photo for stacking reference.\nOnce stacked, Nucleo\u2019s I/O pins are exposed to the top of the HL Shield through staking headers, highlighted in blue rectangles of the previous photo.\nNote that there is no stacking header for pin D0 to D7, thus not accessible once stacked. Nucleo\u2019s RX and TX pins (D0 and D1) are connected to module\u2019s UART.\nConnecting the Debug cable\nConnect the TTL to Serial Debug cable to Nucleo pin D8 and GND as shown in the previous photo\nPins D2 and D8 of Nucleo board will be configured programmatically as an serial port for debug output purpose\nRefer to the datasheet of your TTL cable, to perform the following connection:\nthe TX wire cannot be connected to Nucleo\u2019s pin D2 (RX) as it is not accessible. Not an issue as Debug output does not make use of RX.\nthe RX wire must be connected to Nucleo\u2019s pin D8 (TX)\nthe Ground wire must be connected to Nucleo\u2019s GND pin\nConnect the TTL cable to USB Hub which is connected to your PC/Mac\nIf USB driver is missing, VCP driver for FTDI-based TTL cables can be downloaded\nhere\nIn Step 1, we\u2019ve covered how to:\nConfigure HL Shield and stack it over the Nucleo board\nConnect HL Module\u2019s UART to your host USB port\nConnect a debug cable (additional serial port configured on Nucleo pins D2 & D8) to your host USB port\nReference to USB driver has also been provided\nStep 2: Software Setup\nThis step first introduce an overview of the embedded system to describe the various software components and their interactions with the development host (PC/Mac).\nIt will then guide you through the installation of the required software development environment and components\nEmbedded System Overview\nmbed platform will be used to develop the application. Source code is compiled online using web browser, Nucleo binary code is downloaded then uploaded locally to Nucleo.\nSierra Wireless MQTT Client library (SWIR_MQTTClient) will be leveraged in order to easily establish communication between AirVantage and Nucleo. This library provides 3 functionalities:\nModule management: setting SIM pin code, setting APN, making data call, etc\u2026\nMQTT Client: managing MQTT session with AirVantage, sending/receiving MQTT packets over AT commands.\nMQTT packets are generated and handled by\nPaho MQTTClient library\nwhich implements MQTT protocol.\nLog output facility:\nSWI_TRACE\nmacro enables Nucleo app to output debug traces to a virtual serial port. This latter function is emulated on Nucleo pins D2 & D8 (by default) and trace logs are visible with a serial monitor application bound to the TTL to serial USB port.\nHL Shield wires Nucleo\u2019s default Serial port (pins D0 & D1) to HL module UART. Therefore, Nucleo\u2019s\nSerial\nobject instance is used by SWIR_MQTTClient library to send AT commands to HL module, and shall not be used to output program trace log. For the latter purpose, use\nSWI_TRACE\nmacro instead.\nHL module\u2019s AT interface trace can be visualized with a serial monitor application bound to the HL Shield Main UART USB port.\nSetup Embedded Software Development Components\nGet started with mbed compiler:\nuse your favorite web browser and navigate to\nmbed\n, then go to\nDeveloper Site\nlogin or signup\nClick on\nPlatforms\nthen select NUCLEO-L053R8 device\nOn the Nucleo-L053R8 page, click on\nAdd to your mbed Compiler\nbutton\nClick on\nOpen mbed Compiler\nto launch the development IDE\nCreate a new program with provided Program Name (e.g. Nucleo_AVHL) using\nEmpty Program\ntemplate\nSelect your new program then click on\nImport\nto open Import Wizard\nIn the Libraries tab, drag\nmbed\nlibrary (the official mbed C/C++ SDK for building mbed applications) and drop it onto your project\nIn the Upload tab, click on browse button:\nImport Paho MQTTClient library: select the prebuilt Arduino port of Paho MQTTClient\nzip file available here\nImport SWIR_MQTTClient library V0.92: select the MQTTClient library for Sierra Wireless HL serie modules\nzip file available here\nImport these 2 libraries with a provided Import Name (e.g. Lib)\nSetup Debug output\nUnplug all USB plugs on the HUB Hub, while maintaining this latter plugged to your host computer. The intent here is to disconnect the host from all Nucleo/HL Shield USB cables. All virtual COM ports are thus released on the host.\nDebug trace log for Nucleo app\nLaunch your favorite Serial monitor software or use the provided\nTestCom.exe\nPlug the TTL to Serial USB cable to the USB Hub, a virtual COM port shall be mounted accordingly\nSelect this virtual COM port and choose 115200 baudrate to open this port in the Serial monitor application\nOutput log for HL Module\nLaunch a second instance of your favorite Serial monitor software or use the provided\nTestCom.exe\nConnect the HL Shield Main UART USB port to the USB Hub, a virtual COM port shall be mounted accordingly\nSelect this virtual COM port and choose 115200 baudrate to open this port in the Serial monitor application\nTestCom.exe tip: When plugging/unplugging a USB device, the associated virtual COM port is displayed in TestCom. Identifying the virtual COM to be openned is then made easy in the 2 above steps.\nIn Step 2, we\u2019ve covered the following:\nOverview of the HL module-based Nucleo system\nSoftware Setup :\nmbed development environment\nImport MQTTClient adapter Library for Sierra Wireless HL Serie Modules\nImport Paho MQTTClient Library\nSetup output tracing to view:\nNucleo application debug trace log\nHL Module\u2019s AT interface trace log\nStep 3: STM32Nucleo-AirVantage Interface\nThe mbed-based embedded system has been properly setup in the previous steps. Before developping the Alarm System application on Nucleo let\u2019s:\nDefine the interface between the Nucleo and AirVantage: communication protocol, data flow and type.\nCheck the MQTT connection between these 2 entities\nNote that prior defining the client-server interface we\u2019d need to define the Alarm System use case to figure out the necessary data flow and type.\nAlarm System Use Case\nOn AirVantage portal, the user can turn ON or OFF the Nucleo-based Alarm system\nIf the Alarm is be turned ON, Nucleo board shall arm the alarm and switch on the LED\nThen Nucleo shall, on a regular basis, read motion event from PIR sensor, and publish it to AirVantage\nIf the Alarm is to be turned OFF, Nucleo shall disarm the alarm system and switch off the LED\nNucleo shall not post any data to AirVantage\nThe data flow and type are therefore defined as follow:\nTurnOn Action command from AirVantage to Device of type\nboolean\n. Value\ntrue\nfor\nTurn ON\n,\nfalse\nfor\nTurn OFF\nMotion event from Device to AirVantage of type\ninteger\n. Value\n1\nfor\nMotion detected\n,\n0\nfor\nNo Motion detected\nAlarm System Application Model\nAn embedded application on device-side (e.g. Nucleo) is interfacing with a server-side application on AirVantage in order to exchange predefined data over a predefined communication protocol and authentication scheme:\nServer-side application is defined by an\nApplication Model\n(a XML file)\nAirVantage uses this XML file to figure out how to deal with the device about\nCommunication Protocol\n,\nAuthentication\nand\nData Exchange\n(e.g. variable, settings, commands)\nBased on the use case as described in the previous section, the application model for our Alarm System is defined\nhere\n:\nThe communication protocol is MQTT, and the authentication is based on the device\u2019s IMEI\n<communication>\n<protocol comm-id="IMEI" type="MQTT" />\n</communication>\nThe downstream TurnOn action command and the upstream motion event are defined in an asset labeled\nMy Home\n, exchanged over MQTT protocol:\n<data>\n<encoding type="MQTT">\n<asset default-label="My Home" id="home">\n<setting default-label="Motion Detected" path="motion" type="int"/>\n<command path="TurnOn" default-label="Turn on">\n<parameter id="Alarm" default-label="Alarm" type="boolean" />\n</command>\n</asset>\n</encoding>\n</data>\nThe Application Model for our Alarm System is now defined. Let\u2019s create it on AirVantage with the 2 following procedures:\nCreate Application Package\nSave the the\nAlarm Application Model\nto file with\napp\nfile extension (e.g. appmodel.app)\nZip the app file (e.g.\nappmodel.zip\n)\nThe filename of this zip file is only used for uploading process. AirVantage does not keep track of this zip filename. Only the XML content will be tracked by AirVantage.\nLog into\nAirVantage Web portal\nGo on Develop Activity > My Apps\nClick on the Release button\nRelease Application\nSelect your zip file (e.g.\nappmodel.zip\n)\nOpen Advanced settings and select\nI want to publish my application after releasing it\nFinally, click on Start\nMaking the First MQTT Connection\nBefore developing the Alarm System application, let\u2019s first try to make a MQTT connection between Nucleo and AirVantage\nSWIR_MQTTClient Library provides a Quick Start sample that is intended to be used as a starting point to easily build AirVantage-MQTT-ready application.\nThis starting point application can publish data to and receive data from AirVantage\u2026 without typing a single line of code.\nHowever this sample app has been configured by default for Arduino platform, do the following to adjust it for Nucleo platform:\nGo to the mbed IDE (web browser)\nSelect\nswir_platform_def.h\nfile, disable TARGET_ARDUINO (//#define TARGET_ARDUINO) and enable TARGET_MBED (#define TARGET_MBED)\nRight-click and Rename the provided sample arduino sketch HL-AV_QuickStart.ino (SWIR_MQTTClient/examples/HL_AV_QuickStart) to HL-AV_QuickStart.cpp\nRight-click then Copy HL-AV_QuickStart.cpp file which is still greyed out due to precedent invalid\nino\nfile extension\nRight-click on the top level program folder (e.g. Nucleo-AVHL) then select Paste, now the sample cpp file becomes valid.\nRight-click on the greyed out HL-AV_QuickStart.cpp (in SWIR_MQTTClient/examples/HL_AV_QuickStart) then delete it\nOpen the Quick Start sample program (just select HL-AV_QuickStart.cpp)\nAdjust the SIM PIN code and APN for your SIM card, change the following definitions in the sketch if necessary:\n#define APN                     "yourAPN"\n#define APN_LOGIN               ""                          //your APN login\n#define APN_PASSWORD            ""                          //your APN password\n#define SIM_PIN_CODE            0                           //default is 0000, it\'s an integer!\nClick the\nCompile\nbutton in mbed IDE, this will compile the sample sketch and download the resulting binary\nMake sure that the HL Shield is powered off (unplug power adapter)\nConnect Nucleo board to USB Hub (connected to Host)\nDrag the downloaded mbed compiled binary file and drop it onto the Nucleo mapped drive\nNucleo sample app will automatically run upon program upload completion\nNucleo app logs should be visible in the first serial monitor\nStart the HL Module: power on the HL shield then press and hold the red button for 1 second\nNucleo will attempt to establish MQTT session with AirVantage once data call is ready (module registered to network, CGREG = x,1 or x,5)\nHL Module AT logs should be visible in the second serial monitor\nVerifying MQTT Connection\nThe MQTT connection outcome (fail and success cases) are described hereafter.\nMQTT Connection Failed\n\u201D\u2014 Fail MQTT connect \u2014\u201D log (in serial monitor) indicates an unsuccessful MQTT connection, refer to top-right picture.\nThis is the first connection, your HL Module has not been registered in AirVantage, let\u2019s do the following:\nLog into AirVantage portal\nRelease and Publish the Application Model as described in the previous sections\nCreate Application Package\nand\nRelease Application\nRegister your system with below information, go to\nRegister\nactivity (refer to bottom-right picture)\nSelect the\nType\nof module (as displayed in the serial monitor)\nCopy the Serial Number displayed in serial monitor and pasted it into the\nSerial Number\nfield\nCopy the IMEI 15-digits displayed in serial monitor and pasted it into the\nIMEI/ESN\nfield\nAssign a Name\nClick on\nRegister\nbutton\nAssign the Alarm Application Model to your device, go to\nInventory\nactivity then\nSystems\nSelect your system, as registered in the above steps\nClick on the Edit icon\nIn the\nApplications\nfield, type in the name of the application (i.e. arduino-alarm) and select it\nClick on the Credentials icon\nEnter a password, it shall match the one in the sketch (#define MODULE_AV_PASSWORD), by default it is\nsierra\nClick on Save button\nFrom this point, the Nucleo should be able to establish a MQTT session, continue the verification with the next sub-section\nMQTT Connected\nIf you have already registered your HL Module on AirVantage portal, then make sure that:\nThe Alarm Application Model with MQTT-binding has been created and assigned to your device, refer to case 2 above\nThe password assigned in AirVantage to your System/AppModel is matching the one in the sketch (#define MODULE_AV_PASSWORD), it is\nsierra\nby default\nMQTT Connected\nConnected to AirVantage\n\u201D\u2014 MQTT connected \u2014\u201D log (in serial monitor) indicates a successful MQTT session\nSending data to AirVantage\nThis sample application posts ellapsed milliseconds (since Jan 1st 1970) to AirVantage. The data key name is\nMilliSec\nTo view the data being sent to AirVantage, log into AirVantage portal\nGo to your system monitor page (i.e.\nMonitor\nactivity, go to\nSystems\n, then select Your System)\nPublished data is visible in the\nLast Communication\nwidget\nReceiving data from AirVantage\nThis quick start sketch can also receive incoming data sent by AirVantage\nLog into AirVantage portal\nGo to your system monitor page (i.e.\nMonitor\nactivity, go to\nSystems\n, then select Your System)\nClick on\ndropdown box then select\nCustom Command\nIn the\nApplication\nfield, select the alarm application (i.e. arduino-alarm)\nChoose a\nCommand\nand define\nParameters\nthen click on\nSend Command\nThis data should be received by your Nucleo, it is displayed in the serial monitor\nUpon receiving command from AirVantage, the device should return an acknowlegment message back to AirVantage.\nThis ack message is automatically published (by the SWIR_MQTTClient library) to the /acks/json topic, as shown below\nIn Step 3, we\u2019ve covered how to:\nDefine the use case for the Alarm System which helps to figure out the data flow and type\nCreate the Alarm Application Model that defines the interface between Nucleo and AirVantage\nMake a first MQTT connection with AirVantage without coding\nRegister device in AirVantage and then Assign Alarm Application Model to it\nVerify that Nucleo can publish data to AirVantage\nVerify that Nucleo can receive data from AirVantage\nStep 4: Build an Alarm System\nIn this step, let\u2019s modify the previous sample sketch to build a simple alarm system application. The use case of this Alarm application is described is the Step 3, section\nAlarm System Use Case\n.\nHardware Setup\nLet\u2019s wire the LED to Nucleo\u2019s digital pin D9 exposed to the top of the shield through stacking header, as shown in the picture\nThe short leg pin of the LED shall be wired to the GND\nWire the PIR\u2019s Output to Nucleo\u2019s digital pin D10 exposed to the top of the shield through stacking header, as shown in the picture\nPIR\u2019s GND and VCC pins shall wired to respectively Nucleo\u2019s GND and 5V pins\nApplication Development Guideline\nThe QuickStart sample, provided by the SWIR_MQTTClient library, should be used as a starting point to develop a new application.\nIt is structured as follow:\nConfiguration\n#define\nkeyword is used to declare configurations which can adjusted by altering default values\ne.g. APN, SIM PIN code, Baudrate, MQTT quality of service level, delays, etc\nThis is the right spot to declare additional data key names defined in your application model\nGlobal variables\nSWIR_MQTTClient object instance is needed as it is the interface with the Library\nA variable to keep track of the SIM status (ready or need SIM pin code)\nYou may declare more variables to fulfill your needs\nQuickStart sketch provides a boilerplate code to facilitate the integration with AirVantage\nCheck SIM pin, wait for readiness of data call, make MQTT connection, retry mechanism, perform regular task are handled in a proper sequence\nYou can customize the application as follow:\nAdd your one-time setup code in doCustomSetup() function\nAdd your code to be executed on a regular basis when MQTT session is established in doCustomLoopTask(), called by main\u2019s loop()\nUsually, this is the placeholder to read sensor data and publish them to AirVantage\nAdd your code to execute incoming Commands from AirVantage in messageArrived() function\nHelper functions are provided for your convenience:\nPostData(keyName, value) to publish data (key/value) to AirVantage\nSWI_TRACE macro to print debug trace to serial monitor\nCoding the Alarm System\nLet\u2019s code this application using the QuickStart sketch as a starting point, following the above guideline\nNote the Alarm scenario specific code below can be be activated by enabling the flag ALARM_SCENARIO (#define ALARM_SCENARIO)\nIn mbed IDE, select HL_AV_QuickStart.cpp file\nConfiguration:\nAdd these new definitions for LED and PIR pins\n#define ALARM_STATUS_LED_PIN    D9  //the LED is wired to Nucleo\'s digital pin D9\n#define PIR_PIN                 D10 //the PIR is wired to Nucleo\'s digital pin D10\nChange data key name to match the ones defined in the\nAlarm Application Model\n(defined in Step 3)\nData key names are prefixed with the asset id (i.e. home).\n#define PUBLISH_DATA_NAME       "home.motion"\n#define INCOMING_DATA_NAME      "home.TurnOn.Alarm"\nGlobal variables:\nDeclare this new global variable to track the Alarm status (on/off), default is off. Place this line before the setup() function.\nint     _isAlarmOn = 0;\nDeclare global variables for the LED and PIR pins\nDigitalOut                      _ledAlarmOnOff(ALARM_STATUS_LED_PIN);   //variable binding to this output pin\nDigitalIn                       _pirState(PIR_PIN);                     //variable binding to this input pin\nPublish the motion detection status to AirVantage in the doCustomLoopTask() function\nvoid doCustomLoopTask()\n{\nif (_isAlarmOn)\n{\n//At this point, the MQTT session has been established and the Alarm system has been armed\nif (_pirState)\n{\npostData(PUBLISH_DATA_NAME, 1);     //Motion detected, let\'s post this event to AV\n}\nelse\n{\npostData(PUBLISH_DATA_NAME, 0);     //No Motion detected, let\'s post this event to AV anyway\n}\n}\n}\nHandle AirVantage-originated Commands in the messageArrived() function\nvoid messageArrived(const char* szKey, const char* szValue, const char* szTimestamp)\n{\nSWIR_TRACE(F("\\r\\n>>> Message from AirVantage: %s = %s @ %s\\r\\n"), szKey, szValue, szTimestamp);\n//based on szKey and szValue let\'s turn on/off the alarm on/off LED\nString sKey = String(szKey);\nString sValue = String(szValue);\nif (sKey == INCOMING_DATA_NAME)\n{\nif (sValue == ON_VALUE)\n{\n_ledAlarmOnOff = true;                      //Switch ON LED\n_isAlarmOn = 1;                             //Arm the Alarm System\n}\nelse\n{\n_ledAlarmOnOff = false;                     /Switch OFF LED\n_isAlarmOn = 0;                             //Disarm the Alarm System'}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'        postData(PUBLISH_DATA_NAME, 0);             //Publish message : "home.motion = 0", for consistency\n    }\n\n    return 0;                                       //to indicate that the command has been handled\n}\n\nreturn 1;                                           //to indicate unknown command,\n                                                    //this information will be returned to AirVantage within the ACK message\n'})}),"\n",(0,i.jsx)(n.p,{children:"}\nUpload the Alarm app to Nucleo\nCompile the modified application to retrieved the resulting binary via download\nMake sure that the HL Shield is powered off (unplug power adapter)\nConnect Nucleo to USB Hub (to Host)\nDrag the downloaded mbed compiled binary file and drop it onto the Nucleo mapped drive\nNucleo sample app will automatically run upon program upload completion\nNucleo app logs should be visible in the first serial monitor\nStart the HL Module: power on the HL shield then press and hold the red button for 1 second\nNucleo will attempt to establish MQTT session with AirVantage once data call is ready (module registered to network, CGREG = x,1 or x,5)\nHL Module AT logs should be visible in the second serial monitor\nTesting the Alarm System\nRefer to\nVerifying MQTT Connection\nsection in Step 3 to :\nCheck the MQTT connection with AirVantage\nRemotely activate the Alarm system by sending Custom Command\nTurnOn.Alarm\non AirVantage\nView motion detection events posted to AirVantage\nIn Step 4, we\u2019ve covered :\nNucleo Hardware setup to fulfill the Alarm Use Case\nThe guideline to easily develop an AirVantage-MQTT-ready application\nHow to to develop the Alarm application using the QuickStart sketch as a starting point"})]})}function h(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>s});var o=t(6540);let i={},a=o.createContext(i);function r(e){let n=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(a.Provider,{value:n},e.children)}}}]);